CREATE TABLE admin_audit_logs (
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	ist_time TIMESTAMP WITHOUT TIME ZONE, 
	admin_username VARCHAR(100) NOT NULL, 
	action VARCHAR(100) NOT NULL, 
	endpoint VARCHAR(255), 
	method VARCHAR(10), 
	ip_address VARCHAR(64), 
	device_os VARCHAR(100), 
	browser VARCHAR(100), 
	user_agent TEXT, 
	location_info JSON, 
	changes JSON, 
	status_code INTEGER, 
	success BOOLEAN, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_admin_audit_logs_id ON admin_audit_logs (id);

CREATE TABLE admin_broadcasts (
	id SERIAL NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	body TEXT NOT NULL, 
	target VARCHAR(30), 
	sent_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	sent_count INTEGER, 
	success BOOLEAN, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_admin_broadcasts_id ON admin_broadcasts (id);

CREATE TABLE gps_logs (
	id BIGSERIAL NOT NULL,
	lat FLOAT,
	lon FLOAT,
	speed FLOAT,
	event VARCHAR(30),
	ist_time TIMESTAMP WITHOUT TIME ZONE,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL,
	trip_id INTEGER,
	gps_time TIMESTAMP WITH TIME ZONE,
	source VARCHAR(20),
	PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

CREATE TABLE gps_logs_default PARTITION OF gps_logs DEFAULT;

CREATE INDEX ix_gps_logs_source ON gps_logs (source);
CREATE INDEX ix_gps_logs_created_at ON gps_logs (created_at);
CREATE INDEX ix_gps_logs_trip_id ON gps_logs (trip_id);

CREATE TABLE gps_realtime (
	id BIGSERIAL NOT NULL, 
	lat FLOAT, 
	lon FLOAT, 
	speed FLOAT, 
	event VARCHAR(30), 
	ist_time TIMESTAMP WITHOUT TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	trip_id INTEGER, 
	gps_time TIMESTAMP WITH TIME ZONE, 
	source VARCHAR(20), 
	PRIMARY KEY (id), 
	UNIQUE (trip_id)
);

CREATE INDEX ix_gps_realtime_source ON gps_realtime (source);

CREATE TABLE routes (
	id SERIAL NOT NULL, 
	name VARCHAR NOT NULL, 
	description TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	PRIMARY KEY (id)
);


CREATE TABLE scheduled_notifications (
	id SERIAL NOT NULL, 
	trip_id INTEGER, 
	send_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	title VARCHAR(200) NOT NULL, 
	body TEXT NOT NULL, 
	status VARCHAR(30), 
	updated_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	PRIMARY KEY (id)
);

CREATE INDEX ix_scheduled_notifications_id ON scheduled_notifications (id);

CREATE TABLE bus_stops (
	id SERIAL NOT NULL, 
	route_id INTEGER, 
	name VARCHAR, 
	lat FLOAT, 
	lon FLOAT, 
	order_index INTEGER, 
	morning_order_index INTEGER, 
	evening_order_index INTEGER, 
	morning_time VARCHAR, 
	evening_time VARCHAR, 
	is_morning_origin BOOLEAN, 
	is_morning_destination BOOLEAN, 
	is_evening_origin BOOLEAN, 
	is_evening_destination BOOLEAN, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(route_id) REFERENCES routes (id) ON DELETE CASCADE
);


CREATE TABLE route_geometry_cache (
	id SERIAL NOT NULL, 
	route_id INTEGER NOT NULL, 
	direction VARCHAR(20) NOT NULL, 
	coordinates JSON NOT NULL, 
	computed_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	PRIMARY KEY (id), 
	CONSTRAINT uq_route_geometry_cache UNIQUE (route_id, direction), 
	FOREIGN KEY(route_id) REFERENCES routes (id) ON DELETE CASCADE
);


CREATE TABLE trips (
	id SERIAL NOT NULL, 
	route_id INTEGER NOT NULL, 
	bus_id INTEGER, 
	date DATE, 
	direction VARCHAR NOT NULL, 
	status VARCHAR NOT NULL, 
	started_at TIMESTAMP WITH TIME ZONE, 
	ended_at TIMESTAMP WITH TIME ZONE, 
	late_by_minutes INTEGER, 
	cancellation_reason VARCHAR, 
	eta_notif_sent BOOLEAN, 
	visited_stops JSON, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(route_id) REFERENCES routes (id) ON DELETE CASCADE
);


CREATE TABLE trip_trace (
	id BIGSERIAL NOT NULL, 
	trip_id INTEGER NOT NULL, 
	raw_lat FLOAT NOT NULL, 
	raw_lon FLOAT NOT NULL, 
	snapped_lat FLOAT, 
	snapped_lon FLOAT, 
	speed_kmh FLOAT, 
	osrm_path JSON, 
	gps_time TIMESTAMP WITH TIME ZONE NOT NULL, 
	recorded_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(trip_id) REFERENCES trips (id) ON DELETE CASCADE
);

CREATE INDEX ix_trip_trace_trip_id ON trip_trace (trip_id);

CREATE TABLE users (
	id UUID NOT NULL, 
	email VARCHAR(120), 
	name VARCHAR(120), 
	boarding_stop_id INTEGER, 
	verified BOOLEAN, 
	device_token VARCHAR, 
	notifications_on BOOLEAN, 
	notify_trip_started BOOLEAN NOT NULL, 
	notify_delays BOOLEAN NOT NULL, 
	notify_admin_broadcasts BOOLEAN NOT NULL, 
	proximity_alert_enabled BOOLEAN, 
	proximity_alert_type VARCHAR, 
	proximity_alert_value FLOAT, 
	proximity_alert_for VARCHAR, 
	last_alerted_trip_id INTEGER, 
	boarding_alert_stop_id INTEGER, 
	destination_alert_stop_id INTEGER, 
	last_dest_alerted_trip_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	last_seen TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	UNIQUE (email), 
	FOREIGN KEY(boarding_stop_id) REFERENCES bus_stops (id)
);

CREATE INDEX ix_users_device_token ON users (device_token);

CREATE TABLE in_app_notifications (
	id SERIAL NOT NULL, 
	user_id UUID, 
	title VARCHAR(200) NOT NULL, 
	body TEXT NOT NULL, 
	type VARCHAR(50) NOT NULL, 
	is_read BOOLEAN, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_in_app_notifications_id ON in_app_notifications (id);

CREATE TABLE refresh_tokens (
	id SERIAL NOT NULL, 
	user_id UUID NOT NULL, 
	token_hash VARCHAR(256) NOT NULL, 
	client_type VARCHAR(20) DEFAULT 'mobile' NOT NULL, 
	family_id UUID, 
	rotated BOOLEAN DEFAULT 'false' NOT NULL, 
	expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	UNIQUE (token_hash)
);

CREATE INDEX ix_refresh_tokens_family_id ON refresh_tokens (family_id);
CREATE INDEX ix_refresh_tokens_user_id ON refresh_tokens (user_id);

CREATE TABLE suggestions (
	id SERIAL NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	trip VARCHAR(50), 
	location VARCHAR(100), 
	suggestion TEXT NOT NULL, 
	user_id UUID, 
	status VARCHAR(30), 
	admin_response TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE INDEX ix_suggestions_id ON suggestions (id);

CREATE TABLE user_notification_preferences (
	id SERIAL NOT NULL, 
	user_id UUID, 
	route_id INTEGER, 
	boarding_stop_id INTEGER, 
	destination_stop_id INTEGER, 
	direction VARCHAR, 
	is_active BOOLEAN, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), 
	updated_at TIMESTAMP WITH TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
	FOREIGN KEY(route_id) REFERENCES routes (id) ON DELETE CASCADE, 
	FOREIGN KEY(boarding_stop_id) REFERENCES bus_stops (id), 
	FOREIGN KEY(destination_stop_id) REFERENCES bus_stops (id)
);


